using Impersonate.Domain.Pipelines;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Impersonate.Infrastructure.Persistence.Configurations;
internal sealed class PipelineRunConfiguration:IEntityTypeConfiguration<PipelineRun>{public void Configure(EntityTypeBuilder<PipelineRun>b){b.ToTable("PipelineRuns");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.FeatureRequest).HasMaxLength(PipelineRun.FeatureRequestMaxLength).IsRequired();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.ExecutionWorkerId).HasMaxLength(200);b.Property(x=>x.PlanningContextArtifactReference).HasMaxLength(500);b.Property(x=>x.PlanningContextSummary).HasMaxLength(2000);b.Property(x=>x.PlanningLanguagesJson).HasMaxLength(4000);b.Property(x=>x.PlanningFrameworksJson).HasMaxLength(4000);b.Property(x=>x.PlanningWarningsJson).HasMaxLength(4000);b.HasIndex(x=>new{x.ProjectId,x.CreatedAtUtc});b.HasIndex(x=>new{x.ProjectId,x.Status});b.HasIndex(x=>new{x.Status,x.ExecutionClaimExpiresAtUtc});b.HasOne<Impersonate.Domain.Projects.Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Tasks).WithOne().HasForeignKey(x=>x.PipelineRunId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Events).WithOne().HasForeignKey(x=>x.PipelineRunId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.LoopRun).WithOne().HasForeignKey<LoopRun>(x=>x.PipelineRunId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PlannedTaskConfiguration:IEntityTypeConfiguration<PlannedTask>{public void Configure(EntityTypeBuilder<PlannedTask>b){b.ToTable("PlannedTasks");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Title).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(4000);b.Property(x=>x.AcceptanceCriteriaJson).HasMaxLength(8000);b.Ignore(x=>x.AcceptanceCriteria);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.DependsOnTaskIdsJson).HasMaxLength(8000);b.Property(x=>x.AffectedAreasJson).HasMaxLength(8000);b.Property(x=>x.ChangeType).HasMaxLength(100);b.Property(x=>x.Risk).HasMaxLength(30);b.Property(x=>x.ConflictRisk).HasMaxLength(30);b.Property(x=>x.ExecutionReason).HasMaxLength(1000);b.Property(x=>x.RepositoryEvidenceJson).HasMaxLength(16000);b.Property(x=>x.OrderAdjustmentReason).HasMaxLength(1000);b.HasIndex(x=>new{x.PipelineRunId,x.Sequence}).IsUnique();b.HasMany(x=>x.Attempts).WithOne().HasForeignKey(x=>x.PlannedTaskId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.ReviewDecisions).WithOne().HasForeignKey(x=>x.PlannedTaskId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class TaskAttemptConfiguration:IEntityTypeConfiguration<TaskAttempt>{public void Configure(EntityTypeBuilder<TaskAttempt>b){b.ToTable("TaskAttempts");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.AttemptType).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Provider).HasMaxLength(50);b.Property(x=>x.Model).HasMaxLength(300);b.Property(x=>x.PromptVersion).HasMaxLength(50);b.Property(x=>x.ProviderRequestId).HasMaxLength(200);b.Property(x=>x.Summary).HasMaxLength(2000);b.Property(x=>x.FailureCode).HasMaxLength(100);b.Property(x=>x.FailureReason).HasMaxLength(2000);b.Property(x=>x.ChangedFilesJson).HasMaxLength(16000);b.Property(x=>x.PatchArtifactReference).HasMaxLength(500);b.Property(x=>x.PatchSha256).HasMaxLength(64);b.Property(x=>x.ValidationSummaryJson).HasMaxLength(16000);b.HasIndex(x=>new{x.PlannedTaskId,x.AttemptNumber}).IsUnique();b.HasIndex(x=>x.Status);}}
internal sealed class ExecutionInvocationConfiguration:IEntityTypeConfiguration<ExecutionInvocation>{public void Configure(EntityTypeBuilder<ExecutionInvocation>b){b.ToTable("ExecutionInvocations");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.AgentRole).HasMaxLength(20);b.Property(x=>x.Provider).HasMaxLength(50);b.Property(x=>x.Model).HasMaxLength(300);b.Property(x=>x.PromptVersion).HasMaxLength(50);b.Property(x=>x.ProviderRequestId).HasMaxLength(200);b.Property(x=>x.ResponseType).HasMaxLength(40);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.FailureCode).HasMaxLength(100);b.Property(x=>x.FailureReason).HasMaxLength(2000);b.HasIndex(x=>new{x.TaskAttemptId,x.Sequence}).IsUnique();b.HasOne<TaskAttempt>().WithMany().HasForeignKey(x=>x.TaskAttemptId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Impersonate.Domain.Ai.ModelSelectionDecision>().WithMany().HasForeignKey(x=>x.SelectionDecisionId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class ReviewDecisionConfiguration:IEntityTypeConfiguration<ReviewDecision>{public void Configure(EntityTypeBuilder<ReviewDecision>b){b.ToTable("ReviewDecisions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Decision).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Provider).HasMaxLength(50);b.Property(x=>x.Model).HasMaxLength(300);b.Property(x=>x.PromptVersion).HasMaxLength(50);b.Property(x=>x.ProviderRequestId).HasMaxLength(200);b.Property(x=>x.ReviewedPatchSha256).HasMaxLength(64);b.Property(x=>x.FindingsJson).HasMaxLength(16000);b.Property(x=>x.Summary).HasMaxLength(2000);b.Property(x=>x.Feedback).HasMaxLength(4000);b.HasIndex(x=>new{x.PlannedTaskId,x.CreatedAtUtc});b.HasIndex(x=>new{x.PlannedTaskId,x.IsCurrent});b.HasOne<TaskAttempt>().WithMany().HasForeignKey(x=>x.TaskAttemptId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class LoopRunConfiguration:IEntityTypeConfiguration<LoopRun>{public void Configure(EntityTypeBuilder<LoopRun>b){b.ToTable("LoopRuns");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.LoopDefinitionId).HasMaxLength(100);b.Property(x=>x.LoopDefinitionVersion).HasMaxLength(20);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CurrentStage).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.PipelineRunId).IsUnique();}}
internal sealed class PipelineRunEventConfiguration:IEntityTypeConfiguration<PipelineRunEvent>{public void Configure(EntityTypeBuilder<PipelineRunEvent>b){b.ToTable("PipelineRunEvents");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.EventType).HasMaxLength(100);b.Property(x=>x.PreviousState).HasMaxLength(50);b.Property(x=>x.NewState).HasMaxLength(50);b.Property(x=>x.Message).HasMaxLength(2000);b.HasIndex(x=>new{x.PipelineRunId,x.Sequence}).IsUnique();b.HasIndex(x=>new{x.ProjectId,x.CreatedAtUtc});}}
internal sealed class PlanningAttemptConfiguration:IEntityTypeConfiguration<PlanningAttempt>{public void Configure(EntityTypeBuilder<PlanningAttempt>b){b.ToTable("PlanningAttempts");b.HasKey(x=>x.Id);b.Property(x=>x.Provider).HasMaxLength(50);b.Property(x=>x.Model).HasMaxLength(200);b.Property(x=>x.PromptVersion).HasMaxLength(50);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.FailureCode).HasMaxLength(100);b.Property(x=>x.FailureMessage).HasMaxLength(2000);b.Property(x=>x.ProviderRequestId).HasMaxLength(200);b.HasIndex(x=>new{x.PipelineRunId,x.AttemptNumber}).IsUnique();b.HasIndex(x=>x.Status);b.HasIndex(x=>x.StartedAtUtc);b.HasOne<PipelineRun>().WithMany().HasForeignKey(x=>x.PipelineRunId).OnDelete(DeleteBehavior.Restrict);}}
